/// -----------------------------------------------------------------------
enum transcribe_status {
  TRANSCRIBE_OK(0),
  TRANSCRIBE_ERR_INVALID_ARG(1),
  TRANSCRIBE_ERR_NOT_IMPLEMENTED(2),
  TRANSCRIBE_ERR_FILE_NOT_FOUND(3),
  TRANSCRIBE_ERR_GGUF(4),
  TRANSCRIBE_ERR_UNSUPPORTED_ARCH(5),
  TRANSCRIBE_ERR_UNSUPPORTED_VARIANT(6),
  TRANSCRIBE_ERR_OOM(7),
  TRANSCRIBE_ERR_BACKEND(8),

  /// Reserved; not currently returned.
  TRANSCRIBE_ERR_SAMPLE_RATE(9),
  TRANSCRIBE_ERR_UNSUPPORTED_LANGUAGE(10),
  TRANSCRIBE_ERR_UNSUPPORTED_TASK(11),

  /// Returned by transcribe_run when the caller asks for a timestamp
  /// granularity finer than the model can produce. Compared against
  /// transcribe_capabilities::max_timestamp_kind, which is set per family at
  /// load time. AUTO never trips this code: the dispatcher passes AUTO through
  /// unconditionally and the per-family run() handler resolves it to the
  /// model's maximum when it assembles the result.
  TRANSCRIBE_ERR_UNSUPPORTED_TIMESTAMPS(12),

  /// Returned by transcribe_run when the caller's abort callback returns true
  /// during the run. Partial results from chunks that completed before the
  /// abort are preserved on the session and readable via the normal result
  /// accessors; transcribe_was_aborted distinguishes partial-from-abort from
  /// complete.
  TRANSCRIBE_ERR_ABORTED(13),

  /// Returned by every entry point that takes a caller-owned size- aware struct
  /// (params, stream params, capabilities out, timings out, family extension)
  /// when the supplied struct_size is zero or smaller than the minimum the call
  /// path requires. Distinct from INVALID_ARG so bindings can match on "caller
  /// forgot to call the transcribe_*_init function" specifically.
  TRANSCRIBE_ERR_BAD_STRUCT_SIZE(14),

  /// Reserved; not currently returned.
  TRANSCRIBE_ERR_UNSUPPORTED_PNC(15),

  /// Reserved; not currently returned.
  TRANSCRIBE_ERR_UNSUPPORTED_ITN(16),

  /// Returned by transcribe_run / transcribe_run_batch when the input audio is
  /// longer than the loaded model can process in a single decode.
  /// Hard-context-cap families (LLM-style decoders: qwen3_asr, canary_qwen,
  /// funasr_nano, granite, granite_nar, voxtral, cohere, canary) reject an
  /// over-length clip UP FRONT — before the decode (and, where the binding
  /// limit is the encoder's positional table, before the encoder) — by
  /// comparing the audio's prefill token count against the model's context
  /// window. The usable ceiling is published as
  /// transcribe_capabilities::max_audio_ms, so a caller can size input before
  /// calling rather than discovering the limit on failure.
  TRANSCRIBE_ERR_INPUT_TOO_LONG(17),

  /// Returned by transcribe_run when the decode stopped because it hit the
  /// model's context / generation budget BEFORE the model emitted end-of-stream
  /// — i.e. the transcript is incomplete. This is the "started, couldn't
  /// finish" counterpart to INPUT_TOO_LONG, and it is a hard non-OK status by
  /// design: a truncated transcript must not be mistaken for a complete one.
  TRANSCRIBE_ERR_OUTPUT_TRUNCATED(18);

  final int value;
  const transcribe_status(this.value);

  static transcribe_status fromValue(int value) => switch (value) {
    0 => TRANSCRIBE_OK,
    1 => TRANSCRIBE_ERR_INVALID_ARG,
    2 => TRANSCRIBE_ERR_NOT_IMPLEMENTED,
    3 => TRANSCRIBE_ERR_FILE_NOT_FOUND,
    4 => TRANSCRIBE_ERR_GGUF,
    5 => TRANSCRIBE_ERR_UNSUPPORTED_ARCH,
    6 => TRANSCRIBE_ERR_UNSUPPORTED_VARIANT,
    7 => TRANSCRIBE_ERR_OOM,
    8 => TRANSCRIBE_ERR_BACKEND,
    9 => TRANSCRIBE_ERR_SAMPLE_RATE,
    10 => TRANSCRIBE_ERR_UNSUPPORTED_LANGUAGE,
    11 => TRANSCRIBE_ERR_UNSUPPORTED_TASK,
    12 => TRANSCRIBE_ERR_UNSUPPORTED_TIMESTAMPS,
    13 => TRANSCRIBE_ERR_ABORTED,
    14 => TRANSCRIBE_ERR_BAD_STRUCT_SIZE,
    15 => TRANSCRIBE_ERR_UNSUPPORTED_PNC,
    16 => TRANSCRIBE_ERR_UNSUPPORTED_ITN,
    17 => TRANSCRIBE_ERR_INPUT_TOO_LONG,
    18 => TRANSCRIBE_ERR_OUTPUT_TRUNCATED,
    _ => throw ArgumentError('Unknown value for transcribe_status: $value'),
  };
}

