/// This enum is the source of truth for callers. ggml's log levels do NOT share
/// these numeric values (its DEBUG/INFO/WARN/ERROR ordering differs), so the
/// internal pass-through layer maps ggml levels onto this enum before any
/// message reaches the installed callback; callers only ever see these values.
/// CONT marks a fragment continuing the previous message (ggml emits these for
/// progress output); hosts that want one line per message may join CONT
/// fragments onto the preceding text.
enum transcribe_log_level {
  TRANSCRIBE_LOG_LEVEL_NONE(0),
  TRANSCRIBE_LOG_LEVEL_INFO(1),
  TRANSCRIBE_LOG_LEVEL_WARN(2),
  TRANSCRIBE_LOG_LEVEL_ERROR(3),
  TRANSCRIBE_LOG_LEVEL_DEBUG(4),

  /// continue previous line
  TRANSCRIBE_LOG_LEVEL_CONT(5);

  final int value;
  const transcribe_log_level(this.value);

  static transcribe_log_level fromValue(int value) => switch (value) {
    0 => TRANSCRIBE_LOG_LEVEL_NONE,
    1 => TRANSCRIBE_LOG_LEVEL_INFO,
    2 => TRANSCRIBE_LOG_LEVEL_WARN,
    3 => TRANSCRIBE_LOG_LEVEL_ERROR,
    4 => TRANSCRIBE_LOG_LEVEL_DEBUG,
    5 => TRANSCRIBE_LOG_LEVEL_CONT,
    _ => throw ArgumentError('Unknown value for transcribe_log_level: $value'),
  };
}

typedef transcribe_log_callbackFunction =
    ffi.Void Function(
      ffi.UnsignedInt level,
      ffi.Pointer<ffi.Char> msg,
      ffi.Pointer<ffi.Void> userdata,
    );
typedef Darttranscribe_log_callbackFunction =
    void Function(
      transcribe_log_level level,
      ffi.Pointer<ffi.Char> msg,
      ffi.Pointer<ffi.Void> userdata,
    );
typedef transcribe_log_callback =
    ffi.Pointer<ffi.NativeFunction<transcribe_log_callbackFunction>>;

