/// Timestamp policy: transcribe_run_params_init() requests AUTO, the richest
/// supported output. AUTO requests the richest granularity compatible with the
/// model and the other selected run tasks (for example, a prompt-selected
/// diarization task may not compose with the model's separate timestamp task).
/// The dispatcher never rejects AUTO, and the per-family run() handler resolves
/// it to the finest granularity the model can actually produce when it
/// assembles the result. A non-AUTO request is treated as a ceiling: if the
/// request is finer than the model's max, transcribe_run returns
/// TRANSCRIBE_ERR_UNSUPPORTED_TIMESTAMPS. If the request is coarser-or-equal,
/// the family handler emits only that granularity and any finer per-run data is
/// elided. The actual granularity returned by a run is reported by
/// transcribe_returned_timestamp_kind(session).
enum transcribe_timestamp_kind {
  TRANSCRIBE_TIMESTAMPS_NONE(0),
  TRANSCRIBE_TIMESTAMPS_AUTO(1),
  TRANSCRIBE_TIMESTAMPS_SEGMENT(2),
  TRANSCRIBE_TIMESTAMPS_WORD(3),
  TRANSCRIBE_TIMESTAMPS_TOKEN(4);

  final int value;
  const transcribe_timestamp_kind(this.value);

  static transcribe_timestamp_kind fromValue(int value) => switch (value) {
    0 => TRANSCRIBE_TIMESTAMPS_NONE,
    1 => TRANSCRIBE_TIMESTAMPS_AUTO,
    2 => TRANSCRIBE_TIMESTAMPS_SEGMENT,
    3 => TRANSCRIBE_TIMESTAMPS_WORD,
    4 => TRANSCRIBE_TIMESTAMPS_TOKEN,
    _ => throw ArgumentError(
      'Unknown value for transcribe_timestamp_kind: $value',
    ),
  };
}

