/// Generic header for every typed family extension struct. The kind tag names
/// the family schema (one FourCC-style 32-bit value per schema, allocated in
/// docs/extension-kinds.md); the size is the caller's sizeof of the full
/// extension struct, captured in the caller's translation unit so a newer
/// library only reads what fits.
final class transcribe_ext extends ffi.Struct {
  @ffi.Uint64()
  external int size;

  @ffi.Uint32()
  external int kind;
}

/// Extension slot — the API surface a typed family extension is pointed at.
/// Slot acceptance is a model-and-slot concern; the dispatcher validates `slot`
/// matches the call site before delegating to the family. A stream-only
/// extension pointed at transcribe_run_params is INVALID_ARG, not
/// silently-ignored. Add new slots by appending to this enum (SESSION /
/// MODEL_LOAD / TOKENIZE would each be one new value, no new probe function);
/// do not renumber.
enum transcribe_ext_slot {
  /// transcribe_run_params::family
  TRANSCRIBE_EXT_SLOT_RUN(0),

  /// transcribe_stream_params::family
  TRANSCRIBE_EXT_SLOT_STREAM(1);

  final int value;
  const transcribe_ext_slot(this.value);

  static transcribe_ext_slot fromValue(int value) => switch (value) {
    0 => TRANSCRIBE_EXT_SLOT_RUN,
    1 => TRANSCRIBE_EXT_SLOT_STREAM,
    _ => throw ArgumentError('Unknown value for transcribe_ext_slot: $value'),
  };
}

/// Backend request.
enum transcribe_backend_request {
  TRANSCRIBE_BACKEND_AUTO(0),
  TRANSCRIBE_BACKEND_CPU(1),
  TRANSCRIBE_BACKEND_METAL(2),
  TRANSCRIBE_BACKEND_VULKAN(3),
  TRANSCRIBE_BACKEND_CPU_ACCEL(4),
  TRANSCRIBE_BACKEND_CUDA(5),
  TRANSCRIBE_BACKEND_ROCM(6);

  final int value;
  const transcribe_backend_request(this.value);

  static transcribe_backend_request fromValue(int value) => switch (value) {
    0 => TRANSCRIBE_BACKEND_AUTO,
    1 => TRANSCRIBE_BACKEND_CPU,
    2 => TRANSCRIBE_BACKEND_METAL,
    3 => TRANSCRIBE_BACKEND_VULKAN,
    4 => TRANSCRIBE_BACKEND_CPU_ACCEL,
    5 => TRANSCRIBE_BACKEND_CUDA,
    6 => TRANSCRIBE_BACKEND_ROCM,
    _ => throw ArgumentError(
      'Unknown value for transcribe_backend_request: $value',
    ),
  };
}

/// Opaque process-local compute-device handle. Handles are owned by the
/// runtime, remain valid for the life of the process, and must not be freed.
/// They may be compared for equality but are not persistent identifiers; use
/// transcribe_device_get_info() and its device_id field for persistence.
final class transcribe_device extends ffi.Opaque {}

typedef transcribe_device_t = ffi.Pointer<transcribe_device>;

/// Device type: ggml's vendor-agnostic classification of a device, orthogonal
/// to `kind` below (which carries the vendor: metal/vulkan/cuda/ rocm/...).
/// Backends report this classification themselves, so treat it as a runtime
/// hint about CPU/GPU/IGPU/ACCEL placement rather than a portable
/// hardware-memory taxonomy. The numeric values mirror ggml's device-type enum.
enum transcribe_device_type {
  /// CPU using system memory
  TRANSCRIBE_DEVICE_TYPE_CPU(0),

  /// backend-reported GPU
  TRANSCRIBE_DEVICE_TYPE_GPU(1),

  /// backend-reported integrated GPU
  TRANSCRIBE_DEVICE_TYPE_IGPU(2),

  /// host-memory accelerator (BLAS/AMX)
  TRANSCRIBE_DEVICE_TYPE_ACCEL(3);

  final int value;
  const transcribe_device_type(this.value);

  static transcribe_device_type fromValue(int value) => switch (value) {
    0 => TRANSCRIBE_DEVICE_TYPE_CPU,
    1 => TRANSCRIBE_DEVICE_TYPE_GPU,
    2 => TRANSCRIBE_DEVICE_TYPE_IGPU,
    3 => TRANSCRIBE_DEVICE_TYPE_ACCEL,
    _ => throw ArgumentError(
      'Unknown value for transcribe_device_type: $value',
    ),
  };
}

/// One registered compute device.
final class transcribe_device_info extends ffi.Struct {
  /// sizeof(*this); set by _init()
  @ffi.Uint64()
  external int struct_size;

  /// ggml device name, e.g. "Metal"
  external ffi.Pointer<ffi.Char> name;

  /// human-readable, e.g. "Apple M4 Max"
  external ffi.Pointer<ffi.Char> description;

  /// vendor kind string; see above
  external ffi.Pointer<ffi.Char> kind;

  /// stable hw id (PCI bus id) or NULL
  external ffi.Pointer<ffi.Char> device_id;

  /// reported capacity in bytes, or 0
  @ffi.Uint64()
  external int memory_total;

  /// available bytes snapshot, or 0
  @ffi.Uint64()
  external int memory_free;

  /// CPU/GPU/IGPU/ACCEL axis
  @ffi.UnsignedInt()
  external int device_typeAsInt;

  transcribe_device_type get device_type =>
      transcribe_device_type.fromValue(device_typeAsInt);
}

/// Model load params.
final class transcribe_model_load_params extends ffi.Struct {
  @ffi.Uint64()
