  @ffi.Int32()
  external int n_ctx;
}

/// Per-run params.
final class transcribe_run_params extends ffi.Struct {
  @ffi.Uint64()
  external int struct_size;

  @ffi.UnsignedInt()
  external int taskAsInt;

  transcribe_task get task => transcribe_task.fromValue(taskAsInt);

  @ffi.UnsignedInt()
  external int timestampsAsInt;

  transcribe_timestamp_kind get timestamps =>
      transcribe_timestamp_kind.fromValue(timestampsAsInt);

  @ffi.UnsignedInt()
  external int pncAsInt;

  transcribe_pnc_mode get pnc => transcribe_pnc_mode.fromValue(pncAsInt);

  @ffi.UnsignedInt()
  external int itnAsInt;

  transcribe_itn_mode get itn => transcribe_itn_mode.fromValue(itnAsInt);

  @ffi.UnsignedInt()
  external int diarizeAsInt;

  transcribe_diarize_mode get diarize =>
      transcribe_diarize_mode.fromValue(diarizeAsInt);

  external ffi.Pointer<ffi.Char> language;

  external ffi.Pointer<ffi.Char> target_language;

  @ffi.Bool()
  external bool keep_special_tags;

  external ffi.Pointer<transcribe_ext> family;

  /// spec_k_drafts: n-gram-lookup speculative-decode draft length for the
  /// offline autoregressive decode step. Family-portable strategy knob; the
  /// family decides how K maps to its internal verify graph.
  @ffi.Int32()
  external int spec_k_drafts;
}

/// Capabilities are semantic model properties read from GGUF KV (with
/// architecture defaults filling in absent keys). They are immutable after a
/// successful transcribe_model_load_file() and never change based on backend
/// fallback.
final class transcribe_capabilities extends ffi.Struct {
  @ffi.Uint64()
  external int struct_size;

  @ffi.Int32()
  external int native_sample_rate;

  @ffi.Int()
  external int n_languages;

  external ffi.Pointer<ffi.Pointer<ffi.Char>> languages;

  @ffi.UnsignedInt()
  external int max_timestamp_kindAsInt;

  transcribe_timestamp_kind get max_timestamp_kind =>
      transcribe_timestamp_kind.fromValue(max_timestamp_kindAsInt);

  /// Gate bools with allied struct data. Kept here so reading the struct gives
  /// a coherent picture of "what tasks does this model support and what data
  /// does it expose for them."
  @ffi.Bool()
  external bool supports_language_detect;

  @ffi.Bool()
  external bool supports_translate;

  @ffi.Bool()
  external bool supports_streaming;

  /// supports_spec_decode: gates transcribe_run_params::spec_k_drafts. True
  /// means the family's offline (transcribe_run / transcribe_run_batch) path
  /// implements n-gram-lookup speculative decoding. A non-zero spec_k_drafts on
  /// a model with supports_spec_decode == false is silently ignored — the run
  /// proceeds as ordinary autoregression. This is a soft gate (no error)
  /// because spec is purely a performance strategy; callers can probe this bit
  /// if they want to know whether passing K will actually do anything.
  @ffi.Bool()
  external bool supports_spec_decode;

  /// max_audio_ms: the longest audio this model can process in one
  /// transcribe_run, in milliseconds of 16 kHz mono input. This is the single
  /// number a caller checks to size input before calling.
  @ffi.Int64()
  external int max_audio_ms;

  /// translate_target_languages / n_translate_target_languages: the set of
  /// target language codes accepted for TRANSCRIBE_TASK_TRANSLATE — the
  /// target-side twin of `languages` (which is the valid set for the
  /// transcribe-side `language` hint). supports_translate gates whether
  /// translation runs at all; this list narrows WHICH targets are valid. A
  /// TRANSLATE run whose run_params::target_language is non-NULL and absent
  /// from a non-empty list is rejected with TRANSCRIBE_ERR_UNSUPPORTED_LANGUAGE
  /// before any decode.
  @ffi.Int()
  external int n_translate_target_languages;

  external ffi.Pointer<ffi.Pointer<ffi.Char>> translate_target_languages;
}

/// Per-feature capability probe. Pure yes/no advisories that don't gate any
/// allied struct data live here instead of as boolean fields on
/// transcribe_capabilities. Adding a feature is +1 enum value with no
/// struct_size advance, which makes the surface easy to grow without ABI churn.
enum transcribe_feature {
  TRANSCRIBE_FEATURE_INITIAL_PROMPT(0),
  TRANSCRIBE_FEATURE_TEMPERATURE_FALLBACK(1),
  TRANSCRIBE_FEATURE_LONG_FORM(2),
  TRANSCRIBE_FEATURE_CANCELLATION(3),
  TRANSCRIBE_FEATURE_PNC(4),
  TRANSCRIBE_FEATURE_ITN(5),
  TRANSCRIBE_FEATURE_DIARIZATION(6);

  final int value;
  const transcribe_feature(this.value);

  static transcribe_feature fromValue(int value) => switch (value) {
    0 => TRANSCRIBE_FEATURE_INITIAL_PROMPT,
    1 => TRANSCRIBE_FEATURE_TEMPERATURE_FALLBACK,
    2 => TRANSCRIBE_FEATURE_LONG_FORM,
    3 => TRANSCRIBE_FEATURE_CANCELLATION,
    4 => TRANSCRIBE_FEATURE_PNC,
    5 => TRANSCRIBE_FEATURE_ITN,
    6 => TRANSCRIBE_FEATURE_DIARIZATION,
    _ => throw ArgumentError('Unknown value for transcribe_feature: $value'),
  };
}

typedef transcribe_abort_callbackFunction =
    ffi.Bool Function(ffi.Pointer<ffi.Void> user_data);
typedef Darttranscribe_abort_callbackFunction =
    bool Function(ffi.Pointer<ffi.Void> user_data);

/// Abort callback. Polled between chunks AND between decode steps (after each
/// token). Abort latency is therefore one decode step — typically 10-50 ms on
/// CPU, sub-ms on Metal. Mid-encoder abort is not supported today (would
/// require ggml hooks that do not exist).
typedef transcribe_abort_callback =
    ffi.Pointer<ffi.NativeFunction<transcribe_abort_callbackFunction>>;

/// Effective limits for a specific session. This is the session-level companion
/// to the model-level transcribe_capabilities::max_audio_ms: for families whose
/// audio consumes decoder context, it accounts for the session's
/// transcribe_session_params::n_ctx cap. For encoder-bound families, n_ctx may
/// lower decoder KV memory without lowering the input-audio bound.
final class transcribe_session_limits extends ffi.Struct {
  @ffi.Uint64()
  external int struct_size;

  @ffi.Int32()
  external int effective_n_ctx;

  @ffi.Int64()
  external int effective_max_audio_ms;

  @ffi.Int64()
  external int max_kv_bytes;
}

/// Streaming is a mode on transcribe_session, not a separate handle. A session
/// is in exactly one of four lifecycle states at any time, and the result
/// accessors (transcribe_full_text, segments, words, tokens) return the current
/// raw model snapshot of the active stream.
enum transcribe_stream_state {
  TRANSCRIBE_STREAM_IDLE(0),
  TRANSCRIBE_STREAM_ACTIVE(1),
  TRANSCRIBE_STREAM_FINISHED(2),
  TRANSCRIBE_STREAM_FAILED(3);

  final int value;
  const transcribe_stream_state(this.value);

  static transcribe_stream_state fromValue(int value) => switch (value) {
    0 => TRANSCRIBE_STREAM_IDLE,
    1 => TRANSCRIBE_STREAM_ACTIVE,
    2 => TRANSCRIBE_STREAM_FINISHED,
    3 => TRANSCRIBE_STREAM_FAILED,
    _ => throw ArgumentError(
      'Unknown value for transcribe_stream_state: $value',
    ),
  };
}

/// Generic public commitment policy. Families still own model-specific
/// streaming mechanics (chunk sizes, cache windows, decoder throttles); this
/// enum controls when the session's UI-facing committed_text grows.
enum transcribe_stream_commit_policy {
  TRANSCRIBE_STREAM_COMMIT_AUTO(0),
  TRANSCRIBE_STREAM_COMMIT_ON_FINALIZE(1),
  TRANSCRIBE_STREAM_COMMIT_STABLE_PREFIX(2);

  final int value;
  const transcribe_stream_commit_policy(this.value);

  static transcribe_stream_commit_policy fromValue(int value) =>
      switch (value) {
        0 => TRANSCRIBE_STREAM_COMMIT_AUTO,
        1 => TRANSCRIBE_STREAM_COMMIT_ON_FINALIZE,
        2 => TRANSCRIBE_STREAM_COMMIT_STABLE_PREFIX,
        _ => throw ArgumentError(
          'Unknown value for transcribe_stream_commit_policy: $value',
        ),
      };
}

