/// Per-item results are exposed as caller-owned copy-out structs. Three
/// accessors (transcribe_get_segment / _word / _token) take a row index and a
/// pointer to an init-function-initialized struct; the library writes the row's
/// fields into the caller's buffer.
final class transcribe_segment extends ffi.Struct {
  @ffi.Uint64()
  external int struct_size;

  @ffi.Int64()
  external int t0_ms;

  @ffi.Int64()
  external int t1_ms;

  @ffi.Int()
  external int first_word;

  @ffi.Int()
  external int n_words;

  @ffi.Int()
  external int first_token;

  @ffi.Int()
  external int n_tokens;

  /// session-owned; see lifetime note above
  external ffi.Pointer<ffi.Char> text;

  /// 1-based; 0 = no speaker attribution
  @ffi.Int32()
  external int speaker_id;
}

final class transcribe_word extends ffi.Struct {
  @ffi.Uint64()
  external int struct_size;

  @ffi.Int64()
  external int t0_ms;

  @ffi.Int64()
  external int t1_ms;

  @ffi.Int()
  external int seg_index;

  @ffi.Int()
  external int first_token;

  @ffi.Int()
  external int n_tokens;

  /// session-owned; see lifetime note above
  external ffi.Pointer<ffi.Char> text;
}

/// transcribe_token::p is the per-token probability when the architecture
/// produces one, or NaN when it does not. The semantic of "token probability"
/// varies by family (joint softmax for transducer, per-step softmax for
/// autoregressive, per-frame argmax probability for CTC) and callers should
/// treat it as a confidence hint, not a calibrated probability.
final class transcribe_token extends ffi.Struct {
  @ffi.Uint64()
  external int struct_size;

  @ffi.Int()
  external int id;

  @ffi.Float()
  external double p;

  @ffi.Int64()
  external int t0_ms;

  @ffi.Int64()
  external int t1_ms;

  @ffi.Int()
  external int seg_index;

  @ffi.Int()
  external int word_index;

  /// session-owned; see lifetime note above
  external ffi.Pointer<ffi.Char> text;
}

/// "Who spoke when" rows, populated when the run resolved diarization ON for a
/// model with TRANSCRIBE_FEATURE_DIARIZATION (see transcribe_diarize_mode).
/// Rows are ordered by emission order of the model's speaker turns; rows MAY
/// overlap in time (two speakers talking at once are two overlapping rows). A
/// model that attributes text but carries no timing information reports t0_ms
/// == t1_ms == 0 ("absent" per the zero-sentinel rule).
final class transcribe_speaker_segment extends ffi.Struct {
  @ffi.Uint64()
  external int struct_size;

  @ffi.Int64()
  external int t0_ms;

  @ffi.Int64()
  external int t1_ms;

  /// 1-based; 0 = row not present
  @ffi.Int32()
  external int speaker_id;

  /// confidence hint; NaN = not produced
  @ffi.Float()
  external double p;
}

