/// Voxtral Realtime streaming knobs.
final class transcribe_voxtral_realtime_stream_ext extends ffi.Struct {
  external transcribe_ext ext;

  @ffi.Int32()
  external int num_delay_tokens;

  @ffi.Int32()
  external int min_decode_interval_ms;
}

/// How an initial prompt composes with condition_on_prev_tokens on long-form
/// runs. Matches HF's prompt_condition_type string knob.
enum transcribe_whisper_prompt_condition {
  TRANSCRIBE_WHISPER_PROMPT_FIRST_SEGMENT(0),
  TRANSCRIBE_WHISPER_PROMPT_ALL_SEGMENTS(1);

  final int value;
  const transcribe_whisper_prompt_condition(this.value);

  static transcribe_whisper_prompt_condition fromValue(int value) =>
      switch (value) {
        0 => TRANSCRIBE_WHISPER_PROMPT_FIRST_SEGMENT,
        1 => TRANSCRIBE_WHISPER_PROMPT_ALL_SEGMENTS,
        _ => throw ArgumentError(
          'Unknown value for transcribe_whisper_prompt_condition: $value',
        ),
      };
}

/// Whisper-family run knobs. Reached via transcribe_run_params::family. NULL
/// family selects transcribe_whisper_run_ext_init() values (Whisper's own
/// shipping recipe: temperature fallback on, compression-ratio / avg-logprob /
/// no-speech safety nets active). Callers that want HF library-wide generate()
/// behavior ("all thresholds disabled") set each _thold field to its _DISABLED
/// sentinel.
final class transcribe_whisper_run_ext extends ffi.Struct {
  external transcribe_ext ext;

  /// Initial prompt / prior context.
  external ffi.Pointer<ffi.Char> initial_prompt;

  external ffi.Pointer<ffi.Int32> prompt_tokens;

  @ffi.Size()
  external int n_prompt_tokens;

  /// See transcribe_whisper_prompt_condition above. Default FIRST_SEGMENT.
  @ffi.UnsignedInt()
  external int prompt_conditionAsInt;

  transcribe_whisper_prompt_condition get prompt_condition =>
      transcribe_whisper_prompt_condition.fromValue(prompt_conditionAsInt);

  /// Per HF generation_whisper.py:1853-1918. When true and any prior chunk
  /// decoded successfully at temperature < 0.5, the tail of the prior chunk's
  /// tokens is prepended (under <|startofprev|>) to the next chunk's prefix,
  /// capped at max_prev_context_tokens. Auto- disables for the next chunk when
  /// the prior chunk was accepted at temperature >= 0.5 (matches HF
  /// ":1090-1093").
  @ffi.Bool()
  external bool condition_on_prev_tokens;

  /// Cap for carried prev tokens; default 223 = max_target_positions/2 - 1.
  @ffi.Int32()
  external int max_prev_context_tokens;

  /// first-tier; default 0.0
  @ffi.Float()
  external double temperature;

  /// default 0.2
  @ffi.Float()
  external double temperature_inc;

  /// default 2.4
  @ffi.Float()
  external double compression_ratio_thold;

  /// default -1.0
  @ffi.Float()
  external double logprob_thold;

  /// default 0.6
  @ffi.Float()
  external double no_speech_thold;

  /// Seed for the sampler at temperature > 0. 0 = nondeterministic (matches the
  /// whisper.cpp convention). A nonzero seed produces reproducible output
  /// across runs at matching temperatures. Ignored when temperature == 0.0
  /// (greedy decode is deterministic by construction).
  @ffi.Uint32()
  external int seed;

  /// Seconds. Caps the first emitted timestamp; default 1.0.
  @ffi.Float()
  external double max_initial_timestamp;
}

/// Per-chunk observability: the temperature tier that the fallback loop
/// accepted, the metric values that drove acceptance, and whether the no-speech
/// gate fired. Populated on every successful transcribe_run() call for a
/// Whisper context; one entry per 30-second encoder window that actually
/// decoded (no-speech-skipped chunks still emit an entry).
final class transcribe_whisper_chunk_trace extends ffi.Struct {
  @ffi.Uint64()
  external int struct_size;

  @ffi.Int64()
  external int t0_ms;

  @ffi.Int64()
  external int t1_ms;

  /// the tier that was accepted
  @ffi.Float()
  external double temperature_used;

  @ffi.Float()
  external double compression_ratio;

  @ffi.Float()
  external double avg_logprob;

  @ffi.Float()
  external double no_speech_prob;

  /// chunk output was discarded
  @ffi.Bool()
  external bool no_speech_triggered;

  /// tiers tried before accept (0 = tier 0 accepted)
  @ffi.Int32()
  external int n_fallbacks;
}

final class tcshim_cancel extends ffi.Opaque {}

